// Transform Apify data to standardized schema with enhanced fields
// Maps platform-specific fields to unified format

const transformedLeads = [];

$input.all().forEach((item, index) => {
  const raw = item.json;

  // Skip empty or error items
  if (!raw || raw.error || Object.keys(raw).length === 0) {
    return;
  }

  // Detect source platform based on available fields
  let sourcePlatform = 'Unknown';
  if (raw.profileUrl || raw.linkedInUrl) sourcePlatform = 'LinkedIn';
  else if (raw.title && raw.category) sourcePlatform = 'Google Maps';
  else if (raw.url && raw.url.includes('facebook.com')) sourcePlatform = 'Facebook';

  // LinkedIn field mapping
  if (sourcePlatform === 'LinkedIn') {
    const fullName = raw.fullName || raw.name || '';
    const nameParts = fullName.trim().split(/\s+/);
    const firstName = nameParts[0] || '';
    const lastName = nameParts.slice(1).join(' ') || '';

    transformedLeads.push({
      // Basic fields
      first_name: firstName,
      last_name: lastName,
      full_name: fullName,
      company_name: raw.companyName || raw.company?.name || '',
      job_title: raw.headline || raw.title || '',
      location: raw.location || `${raw.city || ''}, ${raw.state || ''}`.trim(),

      // Contact fields
      email_address: raw.email || '',
      phone_number: raw.phone || raw.phoneNumbers?.[0] || '',
      linkedin_url: raw.profileUrl || raw.url || '',
      company_website: raw.companyWebsite || '',

      // Enhanced Apify fields
      twitter_handle: raw.twitter || '',
      connections_count: raw.connectionsCount || null,
      follower_count: raw.followersCount || null,
      is_premium: raw.isPremium || false,
      current_company_duration: raw.currentCompanyDuration || '',
      skills: raw.skills ? raw.skills.join(', ') : '',
      education: raw.education ? raw.education.map(e => e.schoolName).join(', ') : '',

      // Company fields
      company_size: raw.companySize || raw.company?.employeeCount || null,
      company_industry: raw.industry || raw.company?.industry || '',
      company_location: raw.companyLocation || '',

      // Metadata
      source_platform: sourcePlatform,
      scrape_date: new Date().toISOString().split('T')[0],
      lead_score: null,
      qualification_status: 'Pending'
    });
  }

  // Google Maps field mapping
  else if (sourcePlatform === 'Google Maps') {
    transformedLeads.push({
      // Basic fields (business-focused)
      first_name: '',
      last_name: '',
      full_name: raw.ownerName || '',
      company_name: raw.title || raw.name || '',
      job_title: raw.category || 'Business Owner',
      location: raw.address || `${raw.city || ''}, ${raw.state || ''}`.trim(),

      // Contact fields
      email_address: raw.email || '',
      phone_number: raw.phone || raw.phoneNumber || '',
      linkedin_url: '',
      company_website: raw.website || raw.url || '',

      // Enhanced Apify fields
      twitter_handle: '',
      connections_count: null,
      follower_count: null,
      is_premium: false,
      current_company_duration: '',
      skills: '',
      education: '',

      // Company fields (Google Maps-specific)
      company_size: null,
      company_industry: raw.category || raw.categoryName || '',
      company_location: raw.address || '',
      rating: raw.rating || raw.stars || null,
      review_count: raw.reviewsCount || raw.totalScore || null,
      price_level: raw.priceLevel || '',
      opening_hours: raw.openingHours ? JSON.stringify(raw.openingHours) : '',
      place_id: raw.placeId || '',
      latitude: raw.latitude || raw.location?.lat || null,
      longitude: raw.longitude || raw.location?.lng || null,

      // Metadata
      source_platform: sourcePlatform,
      scrape_date: new Date().toISOString().split('T')[0],
      lead_score: raw.rating ? Math.round(raw.rating) : null,
      qualification_status: 'Pending'
    });
  }

  // Facebook field mapping
  else if (sourcePlatform === 'Facebook') {
    transformedLeads.push({
      // Basic fields (page-focused)
      first_name: '',
      last_name: '',
      full_name: '',
      company_name: raw.name || raw.title || '',
      job_title: raw.category || 'Business Owner',
      location: raw.location || raw.address || '',

      // Contact fields
      email_address: raw.email || raw.emails?.[0] || '',
      phone_number: raw.phone || raw.phoneNumber || '',
      linkedin_url: '',
      company_website: raw.website || raw.url || '',

      // Enhanced Apify fields
      twitter_handle: '',
      connections_count: null,
      follower_count: raw.likes || raw.followersCount || null,
      is_premium: false,
      current_company_duration: '',
      skills: '',
      education: '',

      // Company fields (Facebook-specific)
      company_size: null,
      company_industry: raw.category || '',
      company_location: raw.location || '',
      facebook_url: raw.url || '',
      facebook_about: raw.about || raw.description || '',
      facebook_likes: raw.likes || null,
      facebook_checkins: raw.checkins || null,

      // Metadata
      source_platform: sourcePlatform,
      scrape_date: new Date().toISOString().split('T')[0],
      lead_score: null,
      qualification_status: 'Pending'
    });
  }
});

console.log(`Transformed ${transformedLeads.length} leads from ${$input.all().length} raw items`);

if (transformedLeads.length === 0) {
  return [{ json: { error: 'No leads to transform. All platforms may have failed.' } }];
}

return transformedLeads.map(lead => ({ json: lead }));

// Deduplicate leads across all platforms
// Priority: Email > LinkedIn URL > Company+Name

const uniqueLeads = [];
const seenEmails = new Set();
const seenLinkedInURLs = new Set();
const seenCompanyNames = new Set();

$input.all().forEach((item) => {
  const lead = item.json;

  // Skip error objects
  if (lead.error) {
    console.log('Skipping error item:', lead.error);
    return;
  }

  const email = lead.email_address?.toLowerCase().trim();
  const linkedInURL = lead.linkedin_url?.toLowerCase().trim();
  const companyKey = `${lead.company_name?.toLowerCase().trim()}|${lead.full_name?.toLowerCase().trim()}`;

  // Deduplication logic
  if (email && seenEmails.has(email)) {
    console.log(`Duplicate email skipped: ${email}`);
    return;
  }

  if (linkedInURL && seenLinkedInURLs.has(linkedInURL)) {
    console.log(`Duplicate LinkedIn URL skipped: ${linkedInURL}`);
    return;
  }

  if (lead.company_name && lead.full_name && seenCompanyNames.has(companyKey)) {
    console.log(`Duplicate company+name skipped: ${companyKey}`);
    return;
  }

  // Mark as seen
  if (email) seenEmails.add(email);
  if (linkedInURL) seenLinkedInURLs.add(linkedInURL);
  if (lead.company_name && lead.full_name) seenCompanyNames.add(companyKey);

  // Add lead_id
  lead.lead_id = `LEAD-${new Date().getFullYear()}-${String(uniqueLeads.length + 1).padStart(4, '0')}`;

  // Data quality check
  if (!lead.company_name && !lead.full_name) {
    console.log('Skipping lead with no company or name');
    return;
  }

  uniqueLeads.push(lead);
});

console.log(`Deduplicated: ${$input.all().length} items → ${uniqueLeads.length} unique leads`);

if (uniqueLeads.length === 0) {
  return [{ json: { error: 'No unique leads after deduplication' } }];
}

return uniqueLeads.map(lead => ({ json: lead }));
